import{_ as l,l as s,o as e,c as o,v as r,p as d,x as t,d as n,i as A,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"RAID 级别与写洞","description":"","frontmatter":{"title":"RAID 级别与写洞","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/raid-levels-write-hole.md","filePath":"cs/raid-levels-write-hole.md","lastUpdated":1789023840000}'),c={name:"cs/raid-levels-write-hole.md"};function p(D,a,h,m,u,_){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="raid-级别与写洞" tabindex="-1">RAID 级别与写洞 <a class="header-anchor" href="#raid-级别与写洞" aria-label="Permalink to &quot;RAID 级别与写洞&quot;">​</a></h1><div class="epigraph"><p>RAID5 写数据与奇偶不是一条原子总线事务：崩溃可留下「数据新、奇偶旧」，洞里的块无法从其余盘重建。</p><footer>—— 据 Patterson et al. 对 RAID 级别的分类；Linux MD 对 dirty region / journal 的补丁说明；McKusick 对冗余的讨论</footer></div><p><a href="/cs/md-raid">上一课</a>能装配阵列。Patterson 的级别决定代价。奇偶阵列还有 <strong>写洞</strong>：不是 FS 的 <a href="/cs/ext4-journal">日志</a>，而是条带更新的崩溃窗口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RAID0：条带，无冗余。RAID1：镜像。RAID4：专用奇偶盘，写热点。RAID5：奇偶轮转。RAID6：双奇偶。RAID10：条带加镜像。小写（read-modify-write）：读旧数据与旧奇偶，算新奇偶，写新数据与新奇偶——四次 I/O，顺序一断即洞。缺口：为何全条带写较好；md 的 raid456 可用日志盘或 RMW 顺序；ZFS RAID-Z 用 COW 避免覆盖写洞（存储栈仍要懂洞的定义）。</p><p><span class="marginnote">写洞不是静默比特翻转——那是 scrub 课。洞是崩溃导致的条带不一致。硬件 RAID 用电池后备写缓存假装原子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>大写：凑满条带只写新数据+新奇偶，无需读改。小写：必须 RMW。崩溃恢复：有 bitmap/journal 则重放或重算该区域；无则该条带可能不可重建。对照 <a href="/cs/soft-updates">软更新</a>：都是写序；对象一个是 FS 缓冲，一个是 RAID 条带。对照 dm：同一洞在 dm-raid 同样存在。</p>',8)),(e(),d(E,null,{default:t(()=>[A(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RMW%5B%22%E5%B0%8F%E5%86%99%20RMW%22%5D%20--%3E%20SEQ%5B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%E5%A5%87%E5%81%B6%E5%88%86%E6%AC%A1%E5%86%99%22%5D%0A%20%20SEQ%20--%3E%20HOLE%5B%22%E5%B4%A9%E6%BA%83%E5%88%99%E6%9D%A1%E5%B8%A6%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20FULL%5B%22%E5%85%A8%E6%9D%A1%E5%B8%A6%E5%86%99%22%5D%20--%3E%20ATOM%5B%22%E5%90%8C%E6%9D%A1%E5%B8%A6%E4%B8%80%E6%AC%A1%E6%8F%90%E4%BA%A4%E8%BE%83%E5%A5%BD%22%5D%0A%20%20J%5B%22RAID%20%E6%97%A5%E5%BF%97%22%5D%20--%3E%20REPLAY%5B%22%E9%87%8D%E6%94%BE%E8%A1%A5%E6%B4%9E%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>级别选择是容量、故障数、写放大的权衡。写洞说明「冗余」不等于「更新原子」。FS 的 ordered 模式不能自动填 RAID 洞——两层各管各的。不要把本课写成采购表。</p><p>与 <a href="/cs/fsync">fsync</a>：应用 fsync 成功只保证逻辑设备完成；若 RAID 内部仍重排且无电池，洞仍可能在掉电时出现——依赖实现是否把 flush 做到成员盘。</p><p>实现上：电池后备写缓存把洞推迟到电池耗尽。日记盘或 RAID-Z 的分配即新块，避免覆盖同一条带。全条带写仍要保证那一次条带内各成员的持久顺序。 读法上只引用<a href="/cs/md-raid">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>RAID 级别与写洞</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入纠删码的全部有限域算术——计算机课已有有限域，这里不重写。下一课在映射表上加密：dm-crypt。</p><p>版本字段会变，课序钉的是机制对象「RAID 级别与写洞」，不是某一主线内核的结构体名。 后课默认：奇偶 RAID 有写洞，需日志或 COW 布局缓解。块层加密如何叠在设备上，下一课 dm-crypt。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>级别决定冗余与写放大；RAID5/6 小写有写洞。</li><li>日志盘、全条带、COW 池是不同补法。</li><li>dm-crypt 是下一课。</li><li>出处：Patterson et al.；Linux MD raid456；<em>OSTEP</em> RAID 章。</li></ul>',11))])}const B=l(c,[["render",p]]);export{f as __pageData,B as default};
